//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:				HE_100F_Drive_State
//	CREATOR:			Helgevold - William Veim
//
// REQUIREMENTS: Vacon 100F
// DESCRTIPTION: 	Generer en string med Frekvensomformerens modus/tilstand
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN						DESCRIPTION
//	 1.0.0				2025-03-27		William Veim			Initial release
//	 1.1.0				2026-02-05		William Veim			Updated according to site testing
//
//================================================================================================================================


// Initilize
Wrk_StateValue.Wrd := Inp_State;
Wrk_StateString := '';
Wrk_StateDescription := '';
WRK_StateCode := '';

Wrk_HMIS_Value := WORD_TO_STRING(Wrk_StateValue.Wrd);

IF NOT Wrk_StateValue.Bit[5] AND (Wrk_StateValue.Bit[1] OR Wrk_StateValue.Bit[2]) THEN
	WRK_StateCode := 'RMP';
	Wrk_StateDescription := 'Ramp ongoing';
ELSIF Wrk_StateValue.Bit[1] THEN	
	WRK_StateCode := 'RUN';
	Wrk_StateDescription := 'Running';
ELSIF Wrk_StateValue.Bit[2] THEN	
	WRK_StateCode := 'RUN';
	Wrk_StateDescription := 'Running reverse';
ELSIF Wrk_StateValue.Bit[0] THEN	
	WRK_StateCode := 'RDY';
	Wrk_StateDescription := 'Drive ready';
ELSIF NOT Wrk_StateValue.Bit[0] THEN	
	WRK_StateCode := 'NRDY';
	Wrk_StateDescription := 'Not ready';
END_IF;

// Add HMIS Code
IF TestABit(In:=Cfg_Composition, Pos:=0) THEN
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_HMIS_Value);
END_IF;	

// Add State Code
IF TestABit(In:=Cfg_Composition, Pos:=1) THEN
	IF LEN(Wrk_StateString) > 0 THEN
		Wrk_StateString := CONCAT(Wrk_StateString, Cfg_Delimiter);
	END_IF;
	Wrk_StateString := CONCAT(Wrk_StateString, WRK_StateCode);
END_IF;

// Add State Description
IF TestABit(In:=Cfg_Composition, Pos:=2) THEN
	IF LEN(Wrk_StateString) > 0 THEN
		Wrk_StateString := CONCAT(Wrk_StateString, Cfg_Delimiter);
	END_IF;
	Wrk_StateString := CONCAT(Wrk_StateString, Wrk_StateDescription);
END_IF;

HE_100F_Drive_State := Wrk_StateString;
